import { useEffect, useState } from 'react';
import { MonthValue } from './socrataCache';

type MonthlyData = {
  monthly: MonthValue[];
  updated: string | null;   // ISO timestamp of when the file was generated
  loading: boolean;
  error: string | null;
};

/**
 * Load one of the pre-computed monthly series from public/data/.
 * The files are generated by src/scripts/update-data.mjs (npm run update-data).
 */
export function useMonthlyData(file: string): MonthlyData {
  const [state, setState] = useState<MonthlyData>({
    monthly: [], updated: null, loading: true, error: null,
  });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        // 'no-cache' makes the browser check for a newer file after each data refresh.
        const res = await fetch(`${process.env.PUBLIC_URL}/data/${file}`, { cache: 'no-cache' });
        if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
        const payload: { updated?: string; monthly?: MonthValue[] } = await res.json();
        if (!Array.isArray(payload.monthly)) throw new Error(`${file} has no monthly data`);
        if (!cancelled) {
          setState({
            monthly: payload.monthly, updated: payload.updated ?? null, loading: false, error: null,
          });
        }
      } catch (err: any) {
        if (!cancelled) {
          setState({ monthly: [], updated: null, loading: false, error: String(err?.message ?? err) });
        }
      }
    })();
    return () => { cancelled = true; };
  }, [file]);

  return state;
}
